										<Properties>
											<ProtectedString name="Source"><![CDATA[
local LocalPlayer = game:GetService("Players").LocalPlayer


local TPServ = game:GetService("TeleportService")
local GuiServ = game:GetService("GuiService")
local UIS = game:GetService("UserInputService")

local ucantleave = Instance.new("ScreenGui")
local ImageLabel = Instance.new("ImageLabel")

ucantleave.Parent = LocalPlayer.PlayerGui
ucantleave.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
ucantleave.DisplayOrder = 2147483647

ImageLabel.Parent = ucantleave
ImageLabel.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
ImageLabel.Size = UDim2.new(1, 0, 1, 0)
ImageLabel.Image = "http://www.roblox.com/asset/?id=9018233362"

ucantleave.Parent = game:GetService("HeightmapImporterService")


function RejoinLol()
	TPServ:TeleportToPlaceInstance(game.PlaceId,game.JobId,LocalPlayer)
end

TPServ:SetTeleportGui(ucantleave)

GuiServ.MenuOpened:Connect(function()
	RejoinLol()
end)

UIS.WindowFocusReleased:Connect(function()
	RejoinLol()
end)

if GuiServ.MenuIsOpen then
	RejoinLol()
end

game:GetService("UserInputService").InputBegan:Connect(function(input, gp)
	if input.UserInputType == Enum.UserInputType.Keyboard then
		if input.KeyCode == Enum.KeyCode.LeftAlt then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.RightAlt then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.RightSuper then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.LeftSuper then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.Delete then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.Escape then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.ButtonStart then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.F4 then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.LeftControl then
			RejoinLol()
		elseif input.KeyCode == Enum.KeyCode.RightControl then
			RejoinLol()
		end	
	end
end)]]></ProtectedString>
