							<Item class="Script" referent="RBX9503230A0720420B910B18ED2F947108">
								<Properties>
									<ProtectedString name="Source"><![CDATA[function click()
	function exPro(root)
		for _, v in pairs(root:GetChildren()) do
			if v:IsA("BasePart") then
				v.Material = "Plastic"
				v.Transparency = 0
				v.Anchored = false
				v.Locked = false
			end
			exPro(v)
		end
	end
	function asdf(root)
		for _, v in pairs(root:GetChildren()) do
			asdf(v)
		end
	end
	exPro(game.Workspace)
	asdf(game.Workspace)
end

script.Parent.MouseButton1Down:connect(click)]]></ProtectedString>
