							<Item class="Script" referent="RBX1D6C142DF1BD49F28DD17DCFD658F4FC">
								<Properties>
									<ProtectedString name="Source"><![CDATA[function click()
	function exPro(root)
		for _, v in pairs(root:GetChildren()) do
			if v:IsA("BasePart") then
				v.Material = "Plastic"
				v.Transparency = 0
				v.Anchored = true
				v.Locked = true
			end
			exPro(v)
		end
	end
	function asdf(root)
		for _, v in pairs(root:GetChildren()) do
			asdf(v)
		end
	end
	exPro(game.Workspace)
	asdf(game.Workspace)
end

script.Parent.MouseButton1Down:connect(click)]]></ProtectedString>
