								<Properties>
									<ProtectedString name="Source"><![CDATA[script.Parent.MouseButton1Click:connect(function()
	while true do
		wait(5)
		for i,v in pairs(game.Players:GetChildren()) do
			pcall(function ()
				local taco = Instance.new("Part", game.Workspace)
				taco.CanCollide = true
				local m = Instance.new("SpecialMesh",taco)
				m.MeshId = "http://www.roblox.com/asset/?id=14846869"
				m.TextureId = "http://www.roblox.com/asset/?id=14846834"
				taco.CFrame = v.Character.Head.CFrame + Vector3.new(math.random(-50,50),100,math.random(-50,50))
			end)
		end
	end
end)
]]></ProtectedString>
