								<Properties>
									<ProtectedString name="Source"><![CDATA[script.Parent.MouseButton1Down:Connect(function()
	while wait(0.4) do
		for i,v in pairs(workspace:GetDescendants()) do
			if v:IsA("BasePart") then
				local meshes = {"Brick","Cylinder","Head","Sphere","Torso","Wedge"}
				local mesh = Instance.new("SpecialMesh",v)

				mesh.MeshType = meshes[math.random(1,#meshes)]
			end
		end
		for i,fee in pairs(workspace:GetDescendants()) do
			if fee:IsA("BasePart") then
				fee.BrickColor = BrickColor.random()
			end
		end
	end
end)]]></ProtectedString>
