							<Item class="Script" referent="RBX422F159F74BE47C989AA34338B8E0569">
								<Properties>
									<ProtectedString name="Source"><![CDATA[script.Parent.MouseButton1Down:Connect(function()
	local m = Instance.new("Hint",workspace)
	m.Text = "Anti-Lalol Hub Destroyer Loaded."
	local times = 3
	wait(5)
	m:Destroy()
	for i,v in pairs(game:GetService("Players"):GetPlayers()) do
		while wait() do
			if v:FindFirstChildOfClass("PlayerGui"):FindFirstChild("lIlllIIllllIIIllllIIll") then
				if v ~= script.Parent.Parent.Parent.Parent.Parent.Parent then

					if times ~= 0 then
						v:FindFirstChildOfClass("PlayerGui"):FindFirstChild("lIlllIIllllIIIllllIIll"):Destroy()
						local m = Instance.new("Hint",workspace)
						m.Text = ""..v.Name.."Tried To Turn LALOL Hub Destroyer. ["..times.."Times Left Until Ban]"
					elseif times == 0 then
						v:Kick("We Warned You With The Hint...")
						game:GetService("Players").PlayerAdded:Connect(function(plr)
							if plr == v then
								v:Kick("Do Not Try To Join Back.")
								local m = Instance.new("Hint",workspace)
								m.Text = ""..v.Name.."Tried To Join Again.."
							end
						end)
					end
				end
			end
		end
	end
end)]]></ProtectedString>
