			ctween(nk,"C0",nk0 * CFrame.Angles(math.rad(-20),0,0),7,true)
			ctween(rs,"C0",rs0*CFrame.new(-.7,0,-.7) * CFrame.Angles(math.rad(150),math.rad(0),math.rad(-30)),7)
