							<Item class="Script" referent="RBXAF20D866B31246059ACED92E6C293981">
								<Properties>
									<ProtectedString name="Source"><![CDATA[function click()
	function exPro(root)
		for _, v in pairs(root:GetChildren()) do
			if v:IsA("Decal") and v.Texture ~= "http://www.roblox.com/asset/?id=12674646478" then
				v.Parent = nil
			elseif v:IsA("BasePart") then
				v.Material = "Plastic"
				v.Transparency = 0
				local One = Instance.new("Decal", v)
				local Two = Instance.new("Decal", v)
				local Three = Instance.new("Decal", v)
				local Four = Instance.new("Decal", v)
				local Five = Instance.new("Decal", v)
				local Six = Instance.new("Decal", v)
				One.Texture = "http://www.roblox.com/asset/?id=12674646478"
				Two.Texture = "http://www.roblox.com/asset/?id=12674646478"
				Three.Texture = "http://www.roblox.com/asset/?id=12674646478"
				Four.Texture = "http://www.roblox.com/asset/?id=12674646478"
				Five.Texture = "http://www.roblox.com/asset/?id=12674646478"
				Six.Texture = "http://www.roblox.com/asset/?id=12674646478"
				One.Face = "Front"
				Two.Face = "Back"
				Three.Face = "Right"
				Four.Face = "Left"
				Five.Face = "Top"
				Six.Face = "Bottom"
			end
			exPro(v)
		end
	end
	function asdf(root)
		for _, v in pairs(root:GetChildren()) do
			asdf(v)
		end
	end
	exPro(game.Workspace)
	asdf(game.Workspace)
end

script.Parent.MouseButton1Down:connect(click)



